import prisma from "../../config/postgres";
import { AppError, ERROR_CODES } from "../../common/utils/errorMessages";
import { BackendCustomer, CreateCustomerDto } from "./customer.types";

export const createCustomer = async (
  data: CreateCustomerDto,
  employeeId: string,
  employeeName?: string
): Promise<BackendCustomer> => {
  const existing = await prisma.customer.findUnique({
    where: { gstrNo: data.gstrNo },
  });

  if (existing) {
    throw new AppError(ERROR_CODES.CUSTOMER_ALREADY_EXISTS);
  }

  return prisma.customer.create({
    data: {
      customerName: data.customerName,
      gstrNo: data.gstrNo,
      paymentTerms: data.paymentTerms || "Cash",

      // ✅ IMPORTANT PART
      createdByEmployeeId: employeeId,
      throughVia: employeeName || data.throughVia || null,

      drugLicense: data.drugLicense || null,
      dlExpiry: data.dlExpiry ? new Date(data.dlExpiry) : null,
      address: data.address || null,
      contacts: data.contacts || [],
      remarks: data.remarks || null,
      relationshipStatus: data.relationshipStatus || "Moderate",
      isBlacklisted: data.isBlacklisted || false,
      blacklistReason: data.blacklistReason || null,
      creditLimit: data.creditLimit || 0,
      contactName: data.contactName || null,
      contactPhone: data.contactPhone || null,
      contactEmail: data.contactEmail || null,
      creditApprovalStatus: "Pending",
      kycProfile: data.kycProfile || null,
      gstCopy: data.gstCopy || null,
      annualTurnover: data.annualTurnover || null,
    },
  }) as Promise<BackendCustomer>;
};

export const loginCustomer = async (gstrNo: string, customerID: string): Promise<BackendCustomer> => {
  const customer = await prisma.customer.findFirst({
    where: { gstrNo},
  });

  if (!customer) throw new AppError(ERROR_CODES.CUSTOMER_NOT_FOUND);

  return customer as BackendCustomer;
};

export const getAllCustomers = async (employeeId: string, role?: string): Promise<BackendCustomer[]> => {
  // If user is admin, show all customers; otherwise show only customers created by or assigned to the employee
  const whereCondition = role === "admin" ? {} : {
    OR: [
      { createdByEmployeeId: employeeId },
      { assignedToEmployeeId: employeeId }
    ]
  };

  return prisma.customer.findMany({
    where: whereCondition,
    select: {
      id: true,
      customerName: true,
      address: true,
      creditLimit: true,
      annualTurnover: true,
      paymentTerms: true,
      throughVia: true,
      gstrNo: true,
      kycProfile: true,
      contacts: true,
      isBlacklisted: true,
      relationshipStatus: true,
      gstCopy: true,
      dlExpiry: true,
      assignedToEmployeeId: true,
      assignedAt: true,
      createdAt: true,
      updatedAt: true
    }
  }) as Promise<BackendCustomer[]>;
};



