export const updateCustomer = async (id: string, data: any) => {
  const customer = await prisma.customer.findUnique({
    where: { id },
  });

  if (!customer) {
    throw new AppError(ERROR_CODES.CUSTOMER_NOT_FOUND);
  }

  return prisma.customer.update({
    where: { id },
    data,
  });
};

export const deleteCustomer = async (id: string) => {
  const customer = await prisma.customer.findUnique({
    where: { id },
  });

  if (!customer) {
    throw new AppError(ERROR_CODES.CUSTOMER_NOT_FOUND);
  }

  return prisma.customer.delete({
    where: { id },
  });
};
function safeDate(value: any): Date | null {
  if (!value) return null;

  // Handle Mongo / Excel style objects
  if (typeof value === "object" && value.value) {
    value = value.value;
  }

  const date = new Date(value);

  if (
    isNaN(date.getTime()) ||
    date.getFullYear() > 2100 ||
    date.getFullYear() < 1900
  ) {
    return null;
  }

  return date;
}


export const bulkCreateCustomers = async (customers: any[], employeeId: string) => {
  const transformedCustomers = customers.map(customer => {
    // Start with existing contacts if provided
    const contacts: any[] = Array.isArray(customer.contacts) ? [...customer.contacts] : [];

    // Merge standalone contact fields into contacts array
    if (customer.contactName || customer.contactEmail || customer.contactPhone) {
      contacts.push({
        name: customer.contactName || null,
        email: customer.contactEmail || null,
        phone: customer.contactPhone || null,
        role: customer.contactRole || null, // optional role field
      });
    }

    return {
      customerName: customer.customerName,
      gstrNo: customer.gstrNo || null,
      paymentTerms: customer.paymentTerms || "Cash",
      throughVia: customer.throughVia || null,
      drugLicense: customer.drugLicense || null,
      dlExpiry: safeDate(customer.dlExpiry),
      address: customer.address || null,
      contacts: contacts.length > 0 ? JSON.stringify(contacts) : null, // ✅ save as JSON string
      remarks: customer.remarks || null,
      relationshipStatus: customer.relationshipStatus || "Moderate",
      isBlacklisted: Boolean(customer.isBlacklisted),
      blacklistReason: customer.blacklistReason || null,
      creditLimit: Number(customer.creditLimit) || 0,
      kycProfile: customer.kycProfile || null,
      creditApprovalStatus: "Pending",
      gstCopy: customer.gstCopy || null,
      annualTurnover: customer.annualTurnover || null,
      createdByEmployeeId: employeeId, // ✅ Add employee ID for bulk import
    };
  });

  return prisma.customer.createMany({
    data: transformedCustomers,
    skipDuplicates: true,
  });
};


export const requestCreditApproval = async (
  customerId: string,
  creditLimit: number
) => {
  const customer = await prisma.customer.findUnique({
    where: { id: customerId },
  });

  if (!customer) throw new AppError(ERROR_CODES.CUSTOMER_NOT_FOUND);

  if (customer.isBlacklisted) {
    throw new AppError(ERROR_CODES.BLACKLISTED_CUSTOMER, "This customer is blacklisted and cannot request credit approval.");
  }

  return prisma.customer.update({
    where: { id: customerId },
    data: {
      creditLimit,
      creditApprovalStatus: "Pending",
    },
  });
};


export const blacklistCustomer = async (
  customerId: string,
  blacklistReason: string
) => {
  const customer = await prisma.customer.findUnique({
    where: { id: customerId },
  });

  if (!customer) throw new AppError(ERROR_CODES.CUSTOMER_NOT_FOUND);

  return prisma.customer.update({
    where: { id: customerId },
    data: {
      isBlacklisted: true,
      blacklistReason: blacklistReason,
      blacklistedAt: new Date(),
    },
  });
};

export const bulkAssignCustomers = async (
  customerIds: string[],
  assignedToEmployeeId: string,
  assignedByEmployeeId: string,
  reason?: string,
  remarks?: string
) => {
  // Verify assigned employee exists
  const assignedToEmployee = await prisma.employee.findUnique({
    where: { id: assignedToEmployeeId },
    select: { id: true, name: true, email: true, department: true }
  });

  if (!assignedToEmployee) {
    throw new AppError(ERROR_CODES.EMPLOYEE_NOT_FOUND, "Assigned employee not found");
  }

  const assignedByEmployee = await prisma.employee.findUnique({
    where: { id: assignedByEmployeeId },
    select: { id: true, name: true, email: true, department: true }
  });

  if (!assignedByEmployee) {
    throw new AppError(ERROR_CODES.EMPLOYEE_NOT_FOUND, "Assigning employee not found");
  }

  const results = {
    successful: [] as any[],
    failed: [] as any[]
  };

  for (const customerId of customerIds) {
    try {
      const customer = await prisma.customer.findUnique({
        where: { id: customerId }
      });

      if (!customer) {
        results.failed.push({
          customerId,
          error: "Customer not found"
        });
        continue;
      }

      // Store previous assignment for history
      const previousEmployeeId = customer.assignedToEmployeeId;

      // Update customer assignment
      const updatedCustomer = await prisma.customer.update({
        where: { id: customerId },
        data: {
          assignedToEmployeeId,
          assignedAt: new Date()
        },
        include: {
          assignedToEmployee: {
            select: { id: true, name: true, email: true, department: true }
          }
        }
      });

      // Create assignment history record
      await prisma.customerAssignmentHistory.create({
        data: {
          customerId,
          assignedToEmployeeId,
          assignedByEmployeeId,
          previousEmployeeId,
          reason,
          remarks
        }
      });

      results.successful.push({
        customerId,
        customerName: customer.customerName,
        assignedTo: assignedToEmployee.name,
        assignedAt: new Date()
      });
    } catch (error: any) {
      results.failed.push({
        customerId,
        error: error.message || "Failed to assign customer"
      });
    }
  }

  return results;
};

export const getCustomerAssignmentHistory = async (customerId: string) => {
  const customer = await prisma.customer.findUnique({
    where: { id: customerId }
  });

  if (!customer) {
    throw new AppError(ERROR_CODES.CUSTOMER_NOT_FOUND);
  }

  return prisma.customerAssignmentHistory.findMany({
    where: { customerId },
    include: {
      assignedByEmployee: {
        select: { id: true, name: true, email: true, department: true }
      }
    },
    orderBy: { assignedAt: 'desc' }
  });
};
